_map = json.loads((Path(__file__).resolve().parents[3] / "maps" / "ED" / "eric.json").read_text(encoding="utf-8"))
_code = {}
for _n in _map["nodes"]:
    if _n["level"] == 2: _code.setdefault(_n["name"], []).append(_n["code"])
_missing = [k for k in N_ if k not in _code]
assert not _missing, f"ED names not in map: {_missing}"
T = {c: v for k, v in N_.items() for c in _code[k]}
